import XCTest
@testable import OpenUsage

/// The shipped `.strings` tables (Localization/<lang>.lproj, generated by script/generate_localizations.py).
final class LocalizationTableTests: XCTestCase {
    private static let languages = ["zh-Hans", "zh-Hant", "ja", "ko"]

    private func table(_ language: String) throws -> [String: String] {
        let root = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
        let url = root.appendingPathComponent("Localization/\(language).lproj/Localizable.strings")
        let dict = try XCTUnwrap(NSDictionary(contentsOf: url) as? [String: String], "\(language) table didn't parse")
        return dict
    }

    private func placeholders(_ text: String) -> [String] {
        let regex = try! NSRegularExpression(pattern: #"%(?:\d+\$)?(?:ll)?[@dlfs]|%%"#)
        let range = NSRange(text.startIndex..., in: text)
        return regex.matches(in: text, range: range)
            .map { String(text[Range($0.range, in: text)!]).replacingOccurrences(of: #"\d+\$"#, with: "", options: .regularExpression) }
            .sorted()
    }

    func testEveryLanguageHasTheSameKeysAndPlaceholders() throws {
        let reference = try table("zh-Hans")
        XCTAssertGreaterThan(reference.count, 300)
        for language in Self.languages {
            let other = try table(language)
            XCTAssertEqual(Set(other.keys), Set(reference.keys), "\(language) keys differ from zh-Hans")
            for (key, value) in other {
                XCTAssertFalse(value.isEmpty, "\(language): empty translation for \(key)")
                XCTAssertEqual(placeholders(value), placeholders(key), "\(language): placeholders differ for \(key)")
            }
        }
    }

    func testFormatKeysProduceTheExpectedText() throws {
        let zh = try table("zh-Hans")
        XCTAssertEqual(String(format: try XCTUnwrap(zh["%@ left"]), "52%"), "剩余 52%")
        XCTAssertEqual(String(format: try XCTUnwrap(zh["Resets in %@"]), "3h 25m"), "3h 25m 后重置")
        XCTAssertEqual(String(format: try XCTUnwrap(zh["~%lld%% left at reset"]), 35), "重置时预计剩余约 35%")
        let ko = try table("ko")
        XCTAssertEqual(String(format: try XCTUnwrap(ko["Next refresh in %lldm"]), 4), "4분 후 새로고침")
    }

    func testEnglishFallbackWhenNoTableIsLoaded() {
        // Under `swift test` the main bundle has no .lproj, so helpers return the English text unchanged.
        XCTAssertEqual(tr("No data"), "No data")
        XCTAssertEqual(trf("%@ left", "52%"), "52% left")
    }
}
